import React, { useEffect, useMemo, useRef, useState } from "react";
import { createRoot } from "react-dom/client";
import { BrowserRouter, Link, Route, Routes, useNavigate, useParams } from "react-router-dom";
import "./styles.css";
import logoUrl from "../../assets/jev-codex-pilot-logo.png";

const favicon = document.createElement("link");
favicon.rel = "icon";
favicon.type = "image/png";
favicon.href = logoUrl;
document.head.appendChild(favicon);

type TaskSpec = { description: string };
type DraftAttachment = { id: string; name: string; mimeType: string; base64: string; previewUrl: string };
type JobAttachment = { id: string; name: string; mimeType: string; size: number; path?: string };
type Analysis = { complexity: string; complexity_score?: number; task_types: string[]; model: string; reasoning: string; context_files: string[]; files_to_modify: string[]; rationale: string[]; evaluator?: string; evaluation_usage?: { input_tokens?: number; output_tokens?: number; total_tokens?: number; estimated_cost_usd?: number } };
type Usage = { input_tokens?: number; cached_input_tokens?: number; output_tokens?: number; reasoning_output_tokens?: number };
type ExecutionEvent = { id: string; timestamp: string; kind: string; title: string; detail?: string; status?: string };
type AccountUsage = { capturedAt: string; lifetimeTokens?: number; peakDailyTokens?: number; todayTokens?: number; unavailableReason?: string };
type ExecutionGroup = { id: string; size: number; position: number };
type Execution = { phase: string; model: string; reasoning: string; startedAt: string; lastActivityAt: string; completedAt?: string; pid?: number; threadId?: string; usage?: Usage; accountUsage?: AccountUsage; group?: ExecutionGroup; compactedAfterTask?: boolean; verification: string; events: ExecutionEvent[] };
type Job = { id: string; projectId: string; batchId?: string; order?: number; projectPath: string; tasks: TaskSpec[]; attachments?: JobAttachment[]; status: string; analysis?: Analysis; execution?: Execution; output?: string; error?: string; archivedAt?: string; createdAt: string };
type ProjectRecord = { id: string; name: string; path: string; createdAt: string; updatedAt: string };
type Billing = { balance: number; source: "gateway"; dashboardUrl: string };
type JevUsage = { analyses: number; inputTokens: number; estimatedCostUsd: number };
type Settings = { configured: boolean; maskedApiKey: string };
type ProjectFile = { path: string; size: number };
type ProjectIndex = { path: string; files: ProjectFile[]; count: number; truncated: boolean; hasAgents: boolean };
type ProjectThreadStatus = { threadId?: string; successfulSinceCompaction: number };
type DraftTask = TaskSpec & { id: string; confirmed?: boolean; attachments?: DraftAttachment[] };
type TreeNode = { name: string; path: string; file?: ProjectFile; children: TreeNode[] };
type ProjectDiffFile = { path: string; status: "added" | "modified" | "deleted" | "renamed" | "untracked"; diff: string };
type ProjectDiff = { base: string; files: ProjectDiffFile[] };

const api = async <T,>(path: string, options?: RequestInit): Promise<T> => {
  const response = await fetch(`/api${path}`, { headers: { "Content-Type": "application/json" }, ...options });
  const data = await response.json();
  if (!response.ok) throw new Error(data.error ?? "Something went wrong");
  return data;
};

function useBilling() {
  const [billing, setBilling] = useState<Billing>();
  const [error, setError] = useState("");
  useEffect(() => { const load = () => void api<Billing>("/billing").then(value => { setBilling(value); setError(""); }).catch(reason => setError(reason instanceof Error ? reason.message : String(reason))); load(); const timer = window.setInterval(load, 15_000); return () => clearInterval(timer); }, []);
  return { billing, error };
}

function useJevUsage() {
  const [usage, setUsage] = useState<JevUsage>({ analyses: 0, inputTokens: 0, estimatedCostUsd: 0 });
  useEffect(() => { const load = () => void api<JevUsage>("/usage").then(setUsage).catch(() => undefined); load(); const timer = window.setInterval(load, 1_500); return () => clearInterval(timer); }, []);
  return usage;
}

function Shell({ children, project }: { children: React.ReactNode; project?: ProjectRecord }) {
  const { billing, error } = useBilling(); const usage = useJevUsage(); const [settingsOpen, setSettingsOpen] = useState(false);
  return <div className="app"><header className="topbar"><Link className="brand" to="/"><img className="brand-logo" src={logoUrl} alt=""/><span>JEV Codex Pilot</span></Link><nav><Link to="/">Projects</Link>{project && <><span className="nav-project"><i/> {project.name}</span></>}</nav><div className="jev-session-usage" title="JEV consumption since this API session started"><small>JEV SESSION</small><b>{formatNumber(usage.inputTokens)} tokens · {formatUsd(usage.estimatedCostUsd)}</b></div><a className="credit-pill" href={billing?.dashboardUrl ?? "https://vercel.com/ai-gateway"} target="_blank" rel="noreferrer" title={error || "Live balance retrieved from Vercel AI Gateway."}><span><small>VERCEL AI GATEWAY CREDITS</small><b>{billing ? `$${billing.balance.toFixed(4)}` : error ? "Unavailable" : "—"}</b></span><i>{billing ? "live" : "unavailable"}</i></a><button className="settings-button" type="button" onClick={() => setSettingsOpen(true)} aria-label="Open settings" title="Settings">⚙</button></header>{children}{settingsOpen && <SettingsDialog onClose={() => setSettingsOpen(false)}/>}</div>;
}

function ProjectsHome() {
  const navigate = useNavigate();
  const [projects, setProjects] = useState<ProjectRecord[]>([]);
  const [jobs, setJobs] = useState<Job[]>([]);
  const [path, setPath] = useState("");
  const [name, setName] = useState("");
  const [context, setContext] = useState("");
  const [needsAgents, setNeedsAgents] = useState<boolean>();
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const refreshProjects = async () => { const [nextProjects, nextJobs] = await Promise.all([api<ProjectRecord[]>("/projects"), api<Job[]>("/jobs")]); setProjects(nextProjects); setJobs(nextJobs); };
  useEffect(() => { void refreshProjects(); }, []);
  const inspect = async () => { if (!path.trim()) return; try { const result = await api<ProjectIndex>(`/project?path=${encodeURIComponent(path.trim())}`); setNeedsAgents(!result.hasAgents); } catch { setNeedsAgents(undefined); } };
  const browse = async () => { setError(""); try { const result = await api<{ path: string }>("/system/select-directory", { method: "POST" }); setPath(result.path); if (!name) setName(result.path.split("/").pop() ?? ""); const inspected = await api<ProjectIndex>(`/project?path=${encodeURIComponent(result.path)}`); setNeedsAgents(!inspected.hasAgents); } catch (reason) { if (!/cancelled/i.test(String(reason))) setError(reason instanceof Error ? reason.message : String(reason)); } };
  const create = async (event: React.FormEvent) => { event.preventDefault(); if (!path) return; setBusy(true); setError(""); try { const project = await api<ProjectRecord>("/projects", { method: "POST", body: JSON.stringify({ path, name, context }) }); navigate(`/projects/${project.id}`); } catch (reason) { setError(reason instanceof Error ? reason.message : String(reason)); } finally { setBusy(false); } };
  const removeProject = async (project: ProjectRecord) => {
    const confirmed = window.confirm(`Remove \"${project.name}\" from JEV Codex Pilot?\n\nThis only removes the workspace from this application. The project folder, its files, and local task history will not be deleted. Re-adding the same folder restores its workspace history.`);
    if (!confirmed) return;
    setError("");
    try { await api<ProjectRecord>(`/projects/${project.id}`, { method: "DELETE" }); await refreshProjects(); setNotice("Project removed from JEV Codex Pilot"); window.setTimeout(() => setNotice(""), 2800); }
    catch (reason) { setError(reason instanceof Error ? reason.message : String(reason)); }
  };
  return <Shell><main className="home-main"><section className="home-hero"><div><p className="eyebrow">LOCAL DEVELOPMENT WORKSPACE</p><h1>Every project.<br/><em>One clear cockpit.</em></h1><p>Create a workspace once, keep its task history, and watch independent Codex sessions move your products forward.</p></div><div className="fleet-stats"><span><b>{projects.length}</b>PROJECTS</span><span><b>{jobs.filter(job => job.status === "RUNNING").length}</b>LIVE RUNS</span><span><b>{jobs.filter(job => job.status === "SUCCESS").length}</b>COMPLETED</span></div></section>
    <section className="project-launcher"><div className="launcher-copy"><span className="step">01</span><div><h2>Open a project</h2><p>Describe a new app before its first task; JEV creates its initial AGENTS.md from that context.</p></div></div><form onSubmit={create}><input value={name} onChange={event => setName(event.target.value)} placeholder="Project name"/><div className="new-project-path"><input value={path} onChange={event => setPath(event.target.value)} onBlur={() => void inspect()} placeholder="Absolute folder path"/><button type="button" onClick={browse}>Browse</button></div><textarea className="project-context" value={context} onChange={event => setContext(event.target.value)} placeholder={needsAgents ? "Describe the application context (required: no AGENTS.md found)…" : "Application context (used only if this folder has no AGENTS.md)…"} required={needsAgents} rows={3}/><button className="create-project" disabled={!path || busy || (needsAgents === true && !context.trim())}>{busy ? "Creating…" : "Create Workspace"}<span>→</span></button></form>{error && <div className="alert"><b>Project could not be opened</b><span>{error}</span></div>}</section>
    <section className="project-library"><div className="section-heading"><span className="step">02</span><div><h2>Your projects</h2><p>Each project keeps its own queue, history and Codex thread.</p></div></div>{projects.length ? <div className="project-grid">{projects.map(project => { const projectJobs = jobs.filter(job => job.projectId === project.id); const running = projectJobs.filter(job => job.status === "RUNNING").length; return <div key={project.id} className="project-card-wrap"><button className="project-card" onClick={() => navigate(`/projects/${project.id}`)}><span className="project-letter">{project.name.slice(0, 1).toUpperCase()}</span><div><h3>{project.name}</h3><p>{project.path}</p><small>{projectJobs.length} tasks · {projectJobs.filter(job => job.status === "SUCCESS").length} completed</small></div><span className={running ? "project-live active" : "project-live"}><i/>{running ? `${running} live` : "idle"}</span><b>↗</b></button><button className="remove-project" type="button" onClick={() => void removeProject(project)} disabled={Boolean(running)} title={running ? "Wait for the active Codex execution to finish" : "Remove this project from JEV Codex Pilot"}>Remove</button></div>; })}</div> : <div className="empty-projects"><span>⌁</span><h3>No project registered yet</h3><p>Choose a local folder above to create your first workspace.</p></div>}</section></main>{notice && <div className="toast">✓ {notice}</div>}</Shell>;
}

function ProjectWorkspace() {
  const { id = "" } = useParams();
  const [record, setRecord] = useState<ProjectRecord>();
  const [project, setProject] = useState<ProjectIndex>();
  const [tasks, setTasks] = useState<DraftTask[]>([makeTask()]);
  const [jobs, setJobs] = useState<Job[]>([]);
  const [selectedId, setSelectedId] = useState<string>();
  const [busy, setBusy] = useState("");
  const [error, setError] = useState("");
  const [toast, setToast] = useState("");
  const [agentsOpen, setAgentsOpen] = useState(false);
  const [dragged, setDragged] = useState<number>();
  const [launchingBatchId, setLaunchingBatchId] = useState<string>();
  const [threadStatus, setThreadStatus] = useState<ProjectThreadStatus>();
  const [threadAction, setThreadAction] = useState<"compact" | "clear">();
  const [editingJob, setEditingJob] = useState<Job>();
  const resultRef = useRef<HTMLElement>(null);
  const selected = jobs.find(job => job.id === selectedId);
  useTaskCompletionPing(jobs);

  const refresh = async () => { const [next, nextThreadStatus] = await Promise.all([api<Job[]>(`/jobs?projectId=${encodeURIComponent(id)}`), api<ProjectThreadStatus>(`/projects/${id}/thread/compact`)]); setJobs(next); setThreadStatus(nextThreadStatus); setSelectedId(current => { const currentJob = next.find(job => job.id === current); const active = currentJob?.batchId ? next.find(job => job.batchId === currentJob.batchId && job.status === "RUNNING") : next.find(job => job.status === "RUNNING"); const visible = next.filter(job => !job.archivedAt && job.status !== "SKIPPED"); return active?.id ?? current ?? visible[0]?.id; }); };
  useEffect(() => { void api<ProjectRecord>(`/projects/${id}`).then(async next => { setRecord(next); setProject(await api<ProjectIndex>(`/project?path=${encodeURIComponent(next.path)}`)); }).catch(reason => setError(reason instanceof Error ? reason.message : String(reason))); void refresh(); const timer = window.setInterval(() => void refresh().catch(() => undefined), 900); return () => clearInterval(timer); }, [id]);

  const moveTask = (from: number, to: number) => setTasks(items => { if (to < 0 || to >= items.length) return items; const copy = [...items]; const [item] = copy.splice(from, 1); copy.splice(to, 0, item); return copy; });
  const addImages = async (taskId: string, files: FileList | null) => { const additions = Array.from(files ?? []); if (!additions.length) return; if (additions.some(file => !["image/png", "image/jpeg", "image/gif", "image/webp"].includes(file.type))) { setError("Only PNG, JPEG, GIF, and WebP images can be attached."); return; } if (additions.some(file => file.size > 5 * 1024 * 1024)) { setError("Each attached image must be 5 MB or smaller."); return; } const current = tasks.find(task => task.id === taskId); if ((current?.attachments?.length ?? 0) + additions.length > 4) { setError("Attach at most four images to one task."); return; } try { const images = await Promise.all(additions.map(readDraftImage)); setTasks(items => items.map(item => item.id === taskId ? { ...item, attachments: [...(item.attachments ?? []), ...images] } : item)); setError(""); } catch { setError("The selected image could not be read."); } };
  const analyze = async (event: React.FormEvent) => { event.preventDefault(); const clean = tasks.filter(task => task.description.trim()).map(task => ({ description: task.description.trim(), attachments: task.attachments?.map(({ id: _id, previewUrl: _previewUrl, ...attachment }) => attachment) })); if (!clean.length) return; setBusy("analysis"); setError(""); try { const created = await api<Job[]>("/jobs", { method: "POST", body: JSON.stringify({ projectId: id, tasks: clean }) }); const prepared: Job[] = []; for (const job of created) prepared.push(await api<Job>(`/jobs/${job.id}/prepare`, { method: "POST" })); await refresh(); setSelectedId(prepared[0].id); setTasks([makeTask()]); window.setTimeout(() => resultRef.current?.scrollIntoView({ behavior: "smooth" }), 50); } catch (reason) { setError(reason instanceof Error ? reason.message : String(reason)); } finally { setBusy(""); } };
  const action = async (name: "run-batch" | "command" | "skip") => { if (!selected) return; setError(""); if (name === "run-batch") setLaunchingBatchId(selected.batchId ?? selected.id); try { if (name === "command") { const result = await api<{ command: string }>(`/jobs/${selected.id}/command`, { method: "POST" }); await navigator.clipboard.writeText(result.command); setToast("Codex command copied"); return window.setTimeout(() => setToast(""), 2200); } await api<Job>(`/jobs/${selected.id}/${name}`, { method: "POST" }); if (name === "skip") setSelectedId(undefined); await refresh(); } catch (reason) { if (name === "run-batch") setLaunchingBatchId(undefined); setError(reason instanceof Error ? reason.message : String(reason)); } };
  const archive = async (job: Job, actionName: "archive" | "unarchive") => { setError(""); try { await api<Job>(`/jobs/${job.id}/${actionName}`, { method: "POST" }); if (actionName === "archive" && selectedId === job.id) setSelectedId(undefined); await refresh(); } catch (reason) { setError(reason instanceof Error ? reason.message : String(reason)); } };
  const controlThread = async (actionName: "compact" | "clear") => { setThreadAction(actionName); setError(""); try { const next = await api<ProjectThreadStatus>(`/projects/${id}/thread/${actionName}`, { method: "POST" }); setThreadStatus(next); await refresh(); setToast(actionName === "compact" ? "Codex thread compacted" : "Codex thread cleared; the next task starts fresh"); window.setTimeout(() => setToast(""), 2800); } catch (reason) { setError(reason instanceof Error ? reason.message : String(reason)); } finally { setThreadAction(undefined); } };
  const batchJobs = selected?.batchId ? jobs.filter(job => job.batchId === selected.batchId).sort((a, b) => (a.order ?? 0) - (b.order ?? 0)) : selected ? [selected] : [];
  const reviewJobs = jobs.filter(job => !job.archivedAt && job.status !== "SKIPPED").sort((a, b) => a.createdAt.localeCompare(b.createdAt));
  const reviewIndex = selected ? reviewJobs.findIndex(job => job.id === selected.id) : -1;
  const selectReviewJob = (offset: number) => {
    const next = reviewJobs[reviewIndex + offset];
    if (!next) return;
    setSelectedId(next.id);
    window.setTimeout(() => resultRef.current?.scrollIntoView({ behavior: "smooth", block: "start" }), 20);
  };
  const batchRunning = batchJobs.some(job => job.status === "RUNNING");
  const launchLocked = Boolean(launchingBatchId) || batchRunning;
  const projectRunning = jobs.some(job => job.status === "RUNNING");
  const pendingCount = jobs.filter(job => !job.archivedAt && job.status === "PENDING").length;
  useEffect(() => { if (!launchingBatchId) return; const currentBatch = jobs.filter(job => (job.batchId ?? job.id) === launchingBatchId); if (currentBatch.length > 0 && currentBatch.every(job => ["SUCCESS", "FAILED", "SKIPPED"].includes(job.status))) setLaunchingBatchId(undefined); }, [jobs, launchingBatchId]);
  if (!record) return <Shell><main><div className="loading-state">{error || "Opening project…"}</div></main></Shell>;
  if (project && !project.hasAgents) return <Shell project={record}><main className="workspace-main"><section className="workspace-hero"><div><Link to="/" className="back-link">← All projects</Link><p className="eyebrow">PROJECT SETUP</p><h1>{record.name}</h1><p>{record.path}</p></div></section><section className="workspace-layout"><aside><ProjectTree project={project}/></aside><AgentsSetup projectId={id} onReady={() => setProject(current => current ? { ...current, hasAgents: true } : current)}/></section></main></Shell>;
  return <Shell project={record}><main className="workspace-main"><section className="workspace-hero"><div><Link to="/" className="back-link">← All projects</Link><h1>{record.name}</h1><p>{record.path}</p></div><div className="project-overview"><span><b>{jobs.filter(job => job.status === "PENDING").length}</b>PENDING</span><span><b>{jobs.filter(job => job.status === "RUNNING").length}</b>RUNNING</span><span><b>{jobs.filter(job => job.status === "SUCCESS").length}</b>DONE</span></div></section>
    <section className="workspace-layout"><aside><ProjectTree project={project}/><button type="button" className="open-agents" onClick={() => setAgentsOpen(true)}><span>⌘</span><div><b>Application context</b><small>Open full AGENTS.md</small></div><i>↗</i></button><Link className="open-diff" to={`/projects/${record.id}/diff`}><span>Δ</span><div><b>Git changes</b><small>Review local modifications</small></div><i>→</i></Link><div className="thread-card"><p className="panel-label">CODEX MEMORY</p><b>{threadStatus?.threadId ? "Project thread active" : "New thread"}</b><span>Automatic compaction every 3 successful tasks.</span><small>{threadStatus?.successfulSinceCompaction ?? 0}/3 before next compact</small><div className="thread-actions"><button type="button" onClick={() => void controlThread("compact")} disabled={projectRunning || !threadStatus?.threadId || Boolean(threadAction)} title={projectRunning ? "Wait for the current execution to finish" : "Compact the active Codex thread now"}>{threadAction === "compact" ? "Compacting…" : "/compact"}</button><button type="button" onClick={() => void controlThread("clear")} disabled={projectRunning || !threadStatus?.threadId || Boolean(threadAction)} title={projectRunning ? "Wait for the current execution to finish" : "Archive this Codex thread and start a fresh one next time"}>{threadAction === "clear" ? "Clearing…" : "/clear"}</button></div><em>{projectRunning ? "Controls unlock when Codex is idle." : threadStatus?.threadId ? "Clear archives this thread; project files and task history stay intact." : "Run a task to create a Codex thread."}</em></div></aside><form className="setup-card" onSubmit={analyze}><div className="section-heading"><span className="step">01</span><div><h2>Add work to the queue</h2><p>JEV evaluates every task independently before Codex starts.</p></div><span className="count">{tasks.length} tasks</span></div><div className="task-list">{tasks.map((task, index) => <div className={`task-row ${dragged === index ? "dragging" : ""} ${task.confirmed ? "confirmed" : ""}`} key={task.id} draggable onDragStart={() => setDragged(index)} onDragEnd={() => setDragged(undefined)} onDragOver={event => event.preventDefault()} onDrop={() => { if (dragged !== undefined) moveTask(dragged, index); }}><span className="drag-handle">⠿</span><span className="task-number">{String(index + 1).padStart(2, "0")}</span><div className="task-body"><textarea rows={2} value={task.description} onKeyDown={event => { if (event.ctrlKey && event.key === "Enter") { event.preventDefault(); setTasks(items => items.map(item => item.id === task.id ? { ...item, confirmed: true } : item)); } }} onChange={event => setTasks(items => items.map(item => item.id === task.id ? { ...item, description: event.target.value, confirmed: false } : item))} placeholder="Describe one concrete outcome…"/></div><div className="task-controls"><div className="task-move-controls"><button type="button" disabled={index === 0} onClick={() => moveTask(index, index - 1)} title="Move task up">↑</button><button type="button" disabled={index === tasks.length - 1} onClick={() => moveTask(index, index + 1)} title="Move task down">↓</button></div><button type="button" className={task.confirmed ? "task-confirm confirmed" : "task-confirm"} disabled={!task.description.trim()} onClick={() => setTasks(items => items.map(item => item.id === task.id ? { ...item, confirmed: !item.confirmed } : item))} title={task.confirmed ? "Unvalidate task" : "Validate task"}>{task.confirmed ? "✓" : "✓"}</button><button type="button" onClick={() => setTasks(items => items.length === 1 ? [makeTask()] : items.filter(item => item.id !== task.id))} title="Remove task">×</button></div></div>)}</div><button className="add-task" type="button" onClick={() => setTasks(items => [...items, makeTask()])}><span>＋</span>Add another task</button>{error && <div className="alert"><b>Something needs attention</b><span>{error}</span></div>}<div className="submit-row"><div><b>One task, one JEV decision</b><span>Validate each draft with ✓, or use Ctrl+Enter; analysis remains available for all filled tasks.</span></div><button className="analyze-button" disabled={!tasks.some(task => task.description.trim()) || busy === "analysis"}>{busy ? "JEV is evaluating…" : "Analyze tasks"}<span>→</span></button></div></form></section>
    {jobs.length > 0 && <QueueBoard jobs={jobs} selectedId={selectedId} onSelect={job => { setSelectedId(job.id); window.setTimeout(() => resultRef.current?.scrollIntoView({ behavior: "smooth" }), 20); }} onArchive={archive} onEdit={setEditingJob} onMove={async (job, status) => { try { await api<Job>(`/jobs/${job.id}/move`, { method: "POST", body: JSON.stringify({ status }) }); await refresh(); } catch (reason) { setError(reason instanceof Error ? reason.message : String(reason)); } }}/>}
    {selected && <section className="result-section" ref={resultRef}><div className="section-kicker"><div><p className="eyebrow">TASK {reviewIndex + 1} OF {reviewJobs.length} · PROJECT THREAD</p><h2>{selected.tasks[0]?.description}</h2><span>{selected.projectPath}</span></div><div className="task-review-nav"><button type="button" onClick={() => selectReviewJob(-1)} disabled={reviewIndex <= 0} aria-label="Previous task" title="Previous task">←</button><span>{reviewIndex + 1} / {reviewJobs.length}</span><button type="button" onClick={() => selectReviewJob(1)} disabled={reviewIndex < 0 || reviewIndex >= reviewJobs.length - 1} aria-label="Next task" title="Next task">→</button><Status status={selected.status}/></div></div>{selected.analysis && <Plan analysis={selected.analysis} adjustable={selected.status === "PENDING"} onAdjust={async (dimension, delta) => { try { await api<Job>(`/jobs/${selected.id}/adjust`, { method: "POST", body: JSON.stringify({ dimension, delta }) }); await refresh(); } catch (reason) { setError(reason instanceof Error ? reason.message : String(reason)); } }}/>}<div className="mission-actions"><button className="secondary" onClick={() => action("command")}>Copy CLI command</button><button className="launch" disabled={launchLocked} onClick={() => action("run-batch")}>{launchingBatchId ? "Sequence running…" : batchRunning ? "Sequence running" : `Launch ${pendingCount} task${pendingCount > 1 ? "s" : ""}`}<span>↗</span></button><button className="ghost" disabled={launchLocked} onClick={() => action("skip")}>Skip</button></div>{(selected.execution || selected.error) && <ExecutionPanel job={selected}/>}</section>}
    </main>{agentsOpen && <ProjectAgentsModal projectId={id} onClose={() => setAgentsOpen(false)}/>} {editingJob && <TaskEditorModal job={editingJob} onClose={() => setEditingJob(undefined)} onSave={async (description, images) => { const updated = await api<Job>(`/jobs/${editingJob.id}/edit`, { method: "POST", body: JSON.stringify({ description, attachments: images.length ? images : undefined }) }); await refresh(); setSelectedId(updated.id); setEditingJob(undefined); setToast("Task updated and re-evaluated by JEV"); window.setTimeout(() => setToast(""), 2600); }}/>} {toast && <div className="toast">✓ {toast}</div>}</Shell>;
}

function makeTask(): DraftTask { return { id: crypto.randomUUID(), description: "", attachments: [] }; }
function readDraftImage(file: File): Promise<DraftAttachment> { return new Promise((resolve, reject) => { const reader = new FileReader(); reader.onerror = () => reject(reader.error); reader.onload = () => { const previewUrl = String(reader.result ?? ""); const base64 = previewUrl.split(",", 2)[1]; if (!base64) return reject(new Error("Missing image data")); resolve({ id: crypto.randomUUID(), name: file.name, mimeType: file.type, base64, previewUrl }); }; reader.readAsDataURL(file); }); }
function TaskEditorModal({ job, onClose, onSave }: { job: Job; onClose: () => void; onSave: (description: string, images: Array<Pick<DraftAttachment, "name" | "mimeType" | "base64">>) => Promise<void> }) { const [description, setDescription] = useState(job.tasks[0]?.description ?? ""); const [images, setImages] = useState<DraftAttachment[]>([]); const [error, setError] = useState(""); const [busy, setBusy] = useState(false); const add = async (files: FileList | null) => { const candidates = Array.from(files ?? []); if (!candidates.length) return; if (candidates.some(file => !["image/png", "image/jpeg", "image/gif", "image/webp"].includes(file.type) || file.size > 5 * 1024 * 1024)) { setError("Use PNG, JPEG, GIF, or WebP images no larger than 5 MB."); return; } if (images.length + candidates.length > 4) { setError("Attach at most four new images at once."); return; } try { const nextImages = await Promise.all(candidates.map(readDraftImage)); setImages(current => [...current, ...nextImages]); setError(""); } catch { setError("The selected image could not be read."); } }; const submit = async (event: React.FormEvent) => { event.preventDefault(); setBusy(true); setError(""); try { await onSave(description, images.map(({ name, mimeType, base64 }) => ({ name, mimeType, base64 }))); } catch (reason) { setError(reason instanceof Error ? reason.message : String(reason)); setBusy(false); } }; return <div className="modal-backdrop" role="presentation" onMouseDown={onClose}><form className="task-editor-modal" role="dialog" aria-modal="true" aria-label="Edit pending task" onMouseDown={event => event.stopPropagation()} onSubmit={submit}><header><div><p className="eyebrow">PENDING TASK</p><h2>Edit and re-evaluate</h2><span>Changing the wording replaces the previous JEV recommendation. New images will be passed to Codex when this ticket runs.</span></div><button type="button" onClick={onClose} aria-label="Close task editor">×</button></header><textarea autoFocus value={description} onChange={event => setDescription(event.target.value)} rows={7} placeholder="Describe the intended outcome…"/><div className="editor-attachments"><div><b>Visual references</b><small>Optional · PNG, JPEG, GIF, or WebP · max 5 MB each</small></div><label className="attach-image"><input type="file" accept="image/png,image/jpeg,image/gif,image/webp" multiple onChange={event => { void add(event.currentTarget.files); event.currentTarget.value = ""; }}/><span>＋ Add image</span></label>{images.length > 0 && <div className="editor-image-list">{images.map(image => <figure key={image.id}><img src={image.previewUrl} alt="New task reference"/><figcaption>{image.name}</figcaption><button type="button" onClick={() => setImages(current => current.filter(candidate => candidate.id !== image.id))}>×</button></figure>)}</div>}</div>{error && <p className="agents-error">{error}</p>}<footer><button type="button" className="modal-secondary" onClick={onClose}>Cancel</button><button className="modal-primary" disabled={busy || !description.trim()}>{busy ? "Re-evaluating…" : "Save & re-evaluate"}</button></footer></form></div>; }
function DiffPage() { const { id = "" } = useParams(); const [record, setRecord] = useState<ProjectRecord>(); const [changeSet, setChangeSet] = useState<ProjectDiff>(); const [selectedPath, setSelectedPath] = useState(""); const [error, setError] = useState(""); const load = async () => { try { const [project, diff] = await Promise.all([api<ProjectRecord>(`/projects/${id}`), api<ProjectDiff>(`/projects/${id}/diff`)]); setRecord(project); setChangeSet(diff); setSelectedPath(current => diff.files.some(file => file.path === current) ? current : diff.files[0]?.path ?? ""); setError(""); } catch (reason) { setError(reason instanceof Error ? reason.message : String(reason)); } }; useEffect(() => { void load(); }, [id]); if (!record) return <Shell><main><div className="loading-state">{error || "Opening change review…"}</div></main></Shell>; const selected = changeSet?.files.find(file => file.path === selectedPath); return <Shell project={record}><main className="workspace-main diff-main"><section className="workspace-hero"><div><Link to={`/projects/${id}`} className="back-link">← Project workspace</Link><p className="eyebrow">SOURCE CONTROL REVIEW</p><h1>Changes</h1><p>Read-only comparison with {changeSet?.base === "HEAD" ? "the latest commit or merge (HEAD)" : changeSet?.base ?? "Git"}.</p></div><div className="project-overview"><span><b>{changeSet?.files.length ?? 0}</b>CHANGED FILES</span><span><b>{changeSet?.files.filter(file => file.status === "added" || file.status === "untracked").length ?? 0}</b>ADDED</span><button className="refresh-diff" type="button" onClick={() => void load()}>Refresh</button></div></section>{error ? <div className="alert"><b>Changes could not be read</b><span>{error}</span></div> : <section className="diff-workbench"><aside className="diff-files"><header><b>EXPLORER</b><small>WORKING TREE</small></header>{changeSet?.files.length ? <DiffFileTree files={changeSet.files} selectedPath={selectedPath} onSelect={setSelectedPath}/> : <p>No changes since the latest commit or merge.</p>}</aside><article className="diff-view">{selected ? <><header><span className={`diff-status ${selected.status}`}>{selected.status}</span><b>{selected.path}</b></header><pre>{selected.diff.split("\n").map((line, index) => <code className={line.startsWith("+") && !line.startsWith("+++") ? "addition" : line.startsWith("-") && !line.startsWith("---") ? "deletion" : line.startsWith("@@") ? "hunk" : line.startsWith("diff ") || line.startsWith("+++") || line.startsWith("---") ? "meta" : ""} key={`${index}-${line}`}>{String(index + 1).padStart(4, " ")} {line || " "}{"\n"}</code>)}</pre></> : <div className="diff-empty">Select a changed file to review its diff.</div>}</article></section>}</main></Shell>; }
function DiffFileTree({ files, selectedPath, onSelect }: { files: ProjectDiffFile[]; selectedPath: string; onSelect: (path: string) => void }) { const folders = new Map<string, ProjectDiffFile[]>(); for (const file of files) { const folder = file.path.includes("/") ? file.path.slice(0, file.path.lastIndexOf("/")) : ""; folders.set(folder, [...(folders.get(folder) ?? []), file]); } return <div className="diff-tree">{[...folders.entries()].sort(([a], [b]) => a.localeCompare(b)).map(([folder, entries]) => <details key={folder || "root"} open><summary>{folder || "ROOT"}</summary>{entries.sort((a, b) => a.path.localeCompare(b.path)).map(file => <button type="button" key={file.path} className={file.path === selectedPath ? "active" : ""} onClick={() => onSelect(file.path)}><i className={file.status}/><span>{file.path.split("/").at(-1)}</span><small>{file.status}</small></button>)}</details>)}</div>; }
function AgentsSetup({ projectId, onReady }: { projectId: string; onReady: () => void }) { const [context, setContext] = useState(""); const [error, setError] = useState(""); const [busy, setBusy] = useState(false); const submit = async (event: React.FormEvent) => { event.preventDefault(); setBusy(true); setError(""); try { await api<ProjectRecord>(`/projects/${projectId}/agents`, { method: "POST", body: JSON.stringify({ context }) }); onReady(); } catch (reason) { setError(reason instanceof Error ? reason.message : String(reason)); } finally { setBusy(false); } }; return <form className="setup-card" onSubmit={submit}><div className="section-heading"><span className="step">01</span><div><h2>Describe this application</h2><p>AGENTS.md is required before JEV can analyze work. It will be created from this context and maintained by Codex.</p></div></div><textarea className="project-context" value={context} onChange={event => setContext(event.target.value)} placeholder="What is this application, who is it for, and what constraints matter?" required rows={8}/>{error && <div className="alert"><b>AGENTS.md could not be created</b><span>{error}</span></div>}<div className="submit-row"><div><b>Required project context</b><span>Codex will append a brief delivery-log bullet after each completed feature.</span></div><button className="analyze-button" disabled={busy || !context.trim()}>{busy ? "Creating…" : "Create AGENTS.md"}<span>→</span></button></div></form>; }
function ProjectAgentsModal({ projectId, onClose }: { projectId: string; onClose: () => void }) { const [content, setContent] = useState<string>(); const [error, setError] = useState(""); const [busy, setBusy] = useState(false); useEffect(() => { void (async () => { setBusy(true); try { setContent((await api<{ content: string }>(`/projects/${projectId}/agents`)).content); } catch (reason) { setError(reason instanceof Error ? reason.message : String(reason)); } finally { setBusy(false); } })(); }, [projectId]); const save = async () => { if (content === undefined) return; setBusy(true); setError(""); try { setContent((await api<{ content: string }>(`/projects/${projectId}/agents`, { method: "PUT", body: JSON.stringify({ content }) })).content); } catch (reason) { setError(reason instanceof Error ? reason.message : String(reason)); } finally { setBusy(false); } }; return <div className="modal-backdrop" role="presentation" onMouseDown={onClose}><section className="agents-modal" role="dialog" aria-modal="true" aria-label="Application context" onMouseDown={event => event.stopPropagation()}><header><div><p className="eyebrow">PROJECT CONTEXT</p><h2>AGENTS.md</h2><span>The complete instructions used by Codex for this project.</span></div><button type="button" onClick={onClose} aria-label="Close AGENTS.md">×</button></header><div className="agents-modal-body">{busy && content === undefined ? <p>Loading AGENTS.md…</p> : content !== undefined && <textarea autoFocus value={content} onChange={event => setContent(event.target.value)} spellCheck={false}/>} {error && <p className="agents-error">{error}</p>}</div><footer><span>Changes apply to this project’s AGENTS.md immediately.</span><div><button type="button" className="modal-secondary" onClick={onClose}>Close</button><button type="button" className="modal-primary" onClick={() => void save()} disabled={busy || !content?.trim()}>{busy ? "Saving…" : "Save AGENTS.md"}</button></div></footer></section></div>; }
 function SettingsDialog({ onClose }: { onClose: () => void }) { const [settings, setSettings] = useState<Settings>(); const [apiKey, setApiKey] = useState(""); const [visible, setVisible] = useState(false); const [busy, setBusy] = useState(false); const [error, setError] = useState(""); useEffect(() => { void api<Settings>("/settings").then(setSettings).catch(reason => setError(reason instanceof Error ? reason.message : String(reason))); }, []); const reveal = async () => { if (visible) { setVisible(false); setApiKey(""); return; } setBusy(true); setError(""); try { setApiKey((await api<{ apiKey: string }>("/settings/api-key")).apiKey); setVisible(true); } catch (reason) { setError(reason instanceof Error ? reason.message : String(reason)); } finally { setBusy(false); } }; const save = async (event: React.FormEvent) => { event.preventDefault(); setBusy(true); setError(""); try { const result = await api<{ configured: boolean; maskedApiKey: string }>("/settings", { method: "PUT", body: JSON.stringify({ apiKey }) }); setSettings({ configured: result.configured, maskedApiKey: result.maskedApiKey }); setApiKey(""); setVisible(false); } catch (reason) { setError(reason instanceof Error ? reason.message : String(reason)); } finally { setBusy(false); } }; return <div className="modal-backdrop" role="presentation" onMouseDown={onClose}><form className="settings-modal" role="dialog" aria-modal="true" aria-label="Settings" onMouseDown={event => event.stopPropagation()} onSubmit={save}><header><div><p className="eyebrow">SETTINGS</p><h2>Vercel AI Gateway</h2><span>JEV uses this paid Gateway key. It remains local in <code>config/config.toml</code>.</span></div><button type="button" onClick={onClose} aria-label="Close settings">×</button></header><label>API key for JEV <span>Vercel AI Gateway</span><div className="secret-field"><input type={visible ? "text" : "password"} value={apiKey} onChange={event => setApiKey(event.target.value)} placeholder={settings?.maskedApiKey || "Paste your Vercel AI Gateway key"} autoComplete="off"/><button type="button" onClick={() => void reveal()} disabled={busy || !settings?.configured} aria-label={visible ? "Hide API key" : "Reveal API key"}>{visible ? "◉" : "◌"}</button></div></label><p className="settings-note">Each task shows its own estimated JEV analysis cost after analysis.</p>{error && <p className="agents-error">{error}</p>}<footer><button type="button" className="modal-secondary" onClick={onClose}>Close</button><button className="modal-primary" disabled={busy || !apiKey.trim()}>{busy ? "Saving…" : settings?.configured ? "Replace key" : "Save key"}</button></footer></form></div>; }
function QueueBoard({ jobs, selectedId, onSelect, onArchive, onEdit, onMove }: { jobs: Job[]; selectedId?: string; onSelect: (job: Job) => void; onArchive: (job: Job, action: "archive" | "unarchive") => Promise<void>; onEdit: (job: Job) => void; onMove: (job: Job, status: "PENDING" | "SUCCESS") => Promise<void> }) { const visible = jobs.filter(job => !job.archivedAt && job.status !== "SKIPPED"); const history = jobs.filter(job => job.archivedAt || job.status === "SKIPPED"); const [draggedJobId, setDraggedJobId] = useState<string>(); const moveTo = (status: string) => { const job = visible.find(candidate => candidate.id === draggedJobId); setDraggedJobId(undefined); const allowed = job && ((job.status === "FAILED" && (status === "PENDING" || status === "SUCCESS")) || (job.status === "SUCCESS" && status === "PENDING")); if (allowed) void onMove(job, status as "PENDING" | "SUCCESS"); }; const historyLabel = (job: Job) => job.status === "SKIPPED" ? "SKIPPED" : `COMPLETED — ${job.analysis ? `gpt-5.6-${job.analysis.model} · ${reasoningLabel(job.analysis.reasoning)}` : "Codex model unavailable"}`; return <section className="queue-board"><div className="section-heading"><span className="step">02</span><div><h2>Task queue</h2><p>Drag Success back to Pending when work needs revision. Failed tasks can move to Pending or Success.</p></div></div><div className="queue-columns">{["PENDING", "RUNNING", "SUCCESS", "FAILED"].map(status => <div className={`queue-column ${draggedJobId && status !== "RUNNING" ? "drop-target" : ""}`} key={status} onDragOver={event => { if (draggedJobId && status !== "RUNNING") event.preventDefault(); }} onDrop={() => moveTo(status)}><header><Status status={status}/><b>{visible.filter(job => job.status === status).length}</b></header>{visible.filter(job => job.status === status).map(job => <div key={job.id} className="queue-card-wrap"><button className={job.id === selectedId ? "queue-card active" : "queue-card"} draggable={job.status === "FAILED" || job.status === "SUCCESS"} onDragStart={() => (job.status === "FAILED" || job.status === "SUCCESS") && setDraggedJobId(job.id)} onDragEnd={() => setDraggedJobId(undefined)} onClick={() => onSelect(job)}><small>TASK {(job.order ?? 0) + 1}</small><b>{job.tasks[0]?.description}</b><span>{job.analysis ? `gpt-5.6-${job.analysis.model} · ${reasoningLabel(job.analysis.reasoning)}` : "Waiting for JEV"}{job.attachments?.length ? ` · ${job.attachments.length} image${job.attachments.length === 1 ? "" : "s"}` : ""}</span></button>{status === "PENDING" && <button className="edit-task" title="Edit and re-evaluate this pending task" aria-label={`Edit ${job.tasks[0]?.description ?? "task"}`} onClick={() => onEdit(job)}>✎</button>}{status === "SUCCESS" && <button className="archive-task" title="Archive this completed task" aria-label={`Archive ${job.tasks[0]?.description ?? "task"}`} onClick={() => void onArchive(job, "archive")}>✓</button>}{status === "FAILED" && <button className="failed-success" title="Move this failed task to Success" aria-label={`Validate ${job.tasks[0]?.description ?? "task"}`} onClick={() => void onMove(job, "SUCCESS")}>✓ Validate</button>}</div>)}</div>)}</div>{history.length > 0 && <details className="task-history"><summary>Completed and skipped history <b>{history.length}</b></summary><div>{history.map(job => <article key={job.id}><button type="button" onClick={() => onSelect(job)}><small>{historyLabel(job)}</small><b>{job.tasks[0]?.description}</b></button>{job.archivedAt && <button className="restore-task" type="button" onClick={() => void onArchive(job, "unarchive")}>↶ Undo</button>}</article>)}</div></details>}</section>; }
function useTaskCompletionPing(jobs: Job[]) { const known = useRef(new Map<string, string>()); const audio = useRef<AudioContext | undefined>(undefined); useEffect(() => { for (const job of jobs) { const previous = known.current.get(job.id); if (previous && previous !== job.status && ["SUCCESS", "FAILED", "SKIPPED"].includes(job.status)) { try { const context = audio.current ?? new AudioContext(); audio.current = context; const oscillator = context.createOscillator(); const gain = context.createGain(); oscillator.frequency.value = 880; gain.gain.setValueAtTime(0.055, context.currentTime); gain.gain.exponentialRampToValueAtTime(0.001, context.currentTime + 0.16); oscillator.connect(gain).connect(context.destination); oscillator.start(); oscillator.stop(context.currentTime + 0.16); } catch { /* Audio can be unavailable until the browser permits it. */ } } known.current.set(job.id, job.status); } }, [jobs]); }
function buildTree(files: ProjectFile[]) { const root: TreeNode = { name: "", path: "", children: [] }; for (const file of files.slice(0, 1000)) { let parent = root; const parts = file.path.split("/"); parts.forEach((part, index) => { let node = parent.children.find(child => child.name === part); if (!node) { node = { name: part, path: parts.slice(0, index + 1).join("/"), children: [] }; parent.children.push(node); } if (index === parts.length - 1) node.file = file; parent = node; }); } const sort = (nodes: TreeNode[]) => nodes.sort((a, b) => Number(Boolean(a.file)) - Number(Boolean(b.file)) || a.name.localeCompare(b.name)).forEach(node => sort(node.children)); sort(root.children); return root.children; }
function ProjectTree({ project }: { project?: ProjectIndex }) { const [open, setOpen] = useState(false); const tree = useMemo(() => buildTree(project?.files ?? []), [project]); return <div className="project-tree"><button type="button" className="tree-title" onClick={() => setOpen(value => !value)}><span className="folder-icon">⌑</span><div><b>Project files</b><small>{project ? `${project.count} files indexed` : "Indexing…"}</small></div><span className="tree-toggle">{open ? "−" : "+"}</span></button>{open && <div className="tree-scroll">{tree.length ? tree.map(node => <TreeEntry node={node} depth={0} key={node.path}/>) : <div className="empty-tree">The project is empty.</div>}</div>}</div>; }
function TreeEntry({ node, depth }: { node: TreeNode; depth: number }) { if (!node.file) return <details className="tree-entry" open={depth < 1}><summary style={{ paddingLeft: 12 + depth * 18 }}><span>▸</span> {node.name}</summary>{node.children.map(child => <TreeEntry key={child.path} node={child} depth={depth + 1}/>)}</details>; return <div className="tree-file" style={{ paddingLeft: 34 + depth * 18 }}><span>·</span>{node.name}</div>; }
function Plan({ analysis, adjustable, onAdjust }: { analysis: Analysis; adjustable: boolean; onAdjust: (dimension: "model" | "reasoning", delta: -1 | 1) => Promise<void> }) { const modelLevels = ["luna", "terra", "sol"]; const reasoningLevels = ["low", "medium", "high", "xhigh"]; const modelIndex = modelLevels.indexOf(analysis.model); const reasoningIndex = reasoningLevels.indexOf(analysis.reasoning); const adjustment = (dimension: "model" | "reasoning", delta: -1 | 1) => void onAdjust(dimension, delta); return <div className="plan-grid"><div className="plan-summary"><p className="panel-label">JEV RECOMMENDATION · THIS TASK ONLY</p><div className="recommendation"><div><small>MODEL</small><b>gpt-5.6-{analysis.model}</b></div><div><small>REASONING</small><b>{reasoningLabel(analysis.reasoning)}</b></div><div><small>COMPLEXITY</small><b>{analysis.complexity_score !== undefined ? `${analysis.complexity_score}/10` : analysis.complexity}</b></div></div>{adjustable && <div className="jev-tuning"><div><div><small>MODEL LEVEL</small><b>gpt-5.6-{analysis.model}</b></div><span><button type="button" onClick={() => adjustment("model", -1)} disabled={modelIndex <= 0} aria-label="Lower model one level">−</button><button type="button" onClick={() => adjustment("model", 1)} disabled={modelIndex < 0 || modelIndex >= modelLevels.length - 1} aria-label="Raise model one level">＋</button></span></div><div><div><small>REASONING LEVEL</small><b>{reasoningLabel(analysis.reasoning)}</b></div><span><button type="button" onClick={() => adjustment("reasoning", -1)} disabled={reasoningIndex <= 0} aria-label="Lower reasoning one level">−</button><button type="button" onClick={() => adjustment("reasoning", 1)} disabled={reasoningIndex < 0 || reasoningIndex >= reasoningLevels.length - 1} aria-label="Raise reasoning one level">＋</button></span></div><p>Adjust one level before launching this pending task. The selected model and reasoning will be used by Codex.</p></div>}<div className="type-list"><span>{analysis.evaluator ?? "legacy analyzer"}</span>{analysis.task_types.map(type => <span key={type}>{type.replace("_", " / ")}</span>)}{analysis.evaluation_usage?.total_tokens !== undefined && <span>{analysis.evaluation_usage.total_tokens} JEV tokens</span>}{analysis.evaluation_usage?.estimated_cost_usd !== undefined && <span>≈ {formatUsd(analysis.evaluation_usage.estimated_cost_usd)} JEV cost</span>}</div><ul>{analysis.rationale.map(item => <li key={item}>{item}</li>)}</ul></div><div className="scope-panel"><p className="panel-label">MINIMAL CONTEXT</p><FileGroup title="Context" values={analysis.context_files}/><FileGroup title="Likely to modify" values={analysis.files_to_modify}/></div></div>; }
function FileGroup({ title, values }: { title: string; values: string[] }) { return <div className="file-group"><div><span className="scope-dot context"/><b>{title}</b><small>{values.length}</small></div>{values.length ? <ul>{values.map(value => <li key={value}>{value}</li>)}</ul> : <p>Nothing inferred</p>}</div>; }

function ExecutionPanel({ job }: { job: Job }) {
  const execution = job.execution;
  const consoleRef = useRef<HTMLPreElement>(null);
  const consoleText = useMemo(() => formatCodexConsole(job.output ?? ""), [job.output]);
  useEffect(() => { if (job.status === "RUNNING") consoleRef.current?.scrollTo({ top: consoleRef.current.scrollHeight }); }, [consoleText, job.status]);
  const compactConfirmed = execution?.events.some(event => event.title === "Codex /compact confirmed");
  const shared = Boolean(execution?.group && execution.group.size > 1);
  return <div className="execution-panel">
    <div className="execution-head"><div><span className={job.status === "RUNNING" ? "pulse" : "pulse still"}/><div><p className="panel-label">LIVE EXECUTION</p><h3>{execution?.phase.toLowerCase().replace("_", " ") ?? "Error"}</h3></div></div>{execution && <div className="runtime-meta"><span><small>MODEL USED</small>{execution.model}</span><span><small>REASONING USED</small>{reasoningLabel(execution.reasoning)}</span><span><small>PROCESS</small>{execution.pid ? `PID ${execution.pid}` : "—"}</span><span><small>STARTED</small>{new Date(execution.startedAt).toLocaleTimeString()}</span></div>}</div>
    {execution && <div className="execution-proof"><b>✓ JEV decision applied to Codex</b><span>{execution.model}</span><span>reasoning: {reasoningLabel(execution.reasoning)}</span>{shared && <strong>shared prompt · {execution.group!.size} tasks</strong>}{compactConfirmed && <strong>/compact confirmed by Codex app-server</strong>}</div>}
    {job.error && <div className="execution-error"><b>Execution error</b><span>{job.error}</span></div>}
    {execution && job.status !== "RUNNING" && <><div className="status-report"><div><small>FINAL STATUS</small><b>{verificationLabel(execution.verification)}</b></div><div><small>{shared ? "GROUP INPUT TOKENS" : "TASK INPUT TOKENS"}</small><b>{formatNumber(execution.usage?.input_tokens)}</b></div><div><small>CACHED INPUT</small><b>{formatNumber(execution.usage?.cached_input_tokens)}</b></div><div><small>{shared ? "GROUP OUTPUT TOKENS" : "TASK OUTPUT TOKENS"}</small><b>{formatNumber(execution.usage?.output_tokens)}</b></div><div><small>ACCOUNT TODAY</small><b>{execution.accountUsage?.unavailableReason ? "Unavailable" : formatNumber(execution.accountUsage?.todayTokens)}</b></div><div><small>ACCOUNT LIFETIME</small><b>{execution.accountUsage?.unavailableReason ? "Unavailable" : formatNumber(execution.accountUsage?.lifetimeTokens)}</b></div><div><small>COMPACTION</small><b>{execution.compactedAfterTask ? "Completed" : "Not due"}</b></div></div><p className="codex-usage-note">Task tokens are reported by Codex at the end of this turn. Account figures are a best-effort, account-wide Codex status snapshot{shared ? "; task token totals are shared by this prompt group." : "."}{execution.accountUsage?.unavailableReason ? ` ${execution.accountUsage.unavailableReason}` : ""}</p></>}
    <div className="live-console"><div className="console-bar"><span><i/><i/><i/></span><b>CODEX LIVE CONSOLE</b><small>{job.status === "RUNNING" ? "STREAMING" : job.status}</small></div><pre ref={consoleRef}>{consoleText || "Waiting for the first Codex event…"}<span className="console-cursor">▋</span></pre></div>
    <div className="timeline">{execution?.events.map(event => <div className={`event ${event.kind} ${event.title.includes("/compact") ? "event-compact" : ""}`} key={event.id}><span className="event-line"/><span className={`event-icon ${event.status ?? ""}`}>{event.kind === "command" ? ">_" : event.kind === "file" ? "◇" : event.kind === "error" ? "!" : event.kind === "reasoning" ? "✦" : "✓"}</span><div><div className="event-title"><b>{event.title}</b><time>{new Date(event.timestamp).toLocaleTimeString()}</time></div>{event.detail && <pre>{event.detail}</pre>}</div></div>)}</div>
    {job.output && <details className="raw-output"><summary>View raw Codex JSONL output</summary><pre>{job.output}</pre></details>}
  </div>;
}

function formatCodexConsole(output: string) { return output.split("\n").filter(Boolean).map(line => { if (/^Reading additional input from stdin/i.test(line)) return ""; try { const event = JSON.parse(line) as any; const item = event.item ?? {}; if (event.type === "thread.started") return `● Session started  ${event.thread_id ?? ""}`; if (event.type === "turn.started") return "✦ Codex is reading the project and planning…"; if (event.type === "turn.completed") return `✓ Turn completed  ${JSON.stringify(event.usage ?? {})}`; if (event.type === "turn.failed" || event.type === "error") return `! ERROR  ${JSON.stringify(event.error ?? event.message ?? event)}`; if (item.type === "command_execution") { const command = String(item.command ?? ""); const result = String(item.aggregated_output ?? "").trim().slice(-4000); return item.status === "in_progress" ? `$ ${command}` : result || `✓ Command finished with exit code ${String(item.exit_code ?? 0)}`; } if (item.type === "agent_message") return String(item.text ?? ""); if (/reason/i.test(item.type ?? "")) return `◆ ${String(item.text ?? "Reasoning…")}`; if (/file|change|patch/i.test(item.type ?? "")) return `◇ Files changed  ${JSON.stringify(item.changes ?? item.path ?? item).slice(0, 4000)}`; return ""; } catch { return line.slice(0, 4000); } }).filter(Boolean).join("\n\n"); }
function verificationLabel(value: string) { return value === "functional_verified" ? "Functionally verified" : value === "tests_passed" ? "Automated tests passed" : value === "build_only" ? "Build only · behavior unverified" : "No verification detected"; }
function reasoningLabel(value: string) { return value === "xhigh" ? "Extra high" : value; }
function formatNumber(value?: number) { return value === undefined ? "—" : new Intl.NumberFormat().format(value); }
function formatUsd(value: number) { return new Intl.NumberFormat(undefined, { style: "currency", currency: "USD", minimumFractionDigits: 4, maximumFractionDigits: 6 }).format(value); }
function Status({ status }: { status: string }) { return <span className={`status status-${status.toLowerCase()}`}><i>{status === "SUCCESS" ? "✓" : status === "FAILED" ? "!" : ""}</i>{status}</span>; }

createRoot(document.getElementById("root")!).render(<BrowserRouter><Routes><Route path="/" element={<ProjectsHome/>}/><Route path="/projects/:id" element={<ProjectWorkspace/>}/><Route path="/projects/:id/diff" element={<DiffPage/>}/><Route path="*" element={<ProjectsHome/>}/></Routes></BrowserRouter>);
